SELECT id, symbol, interval_code, generated_at, decision, market_regime, liquidity_status, atr_at_signal, atr_percent, atr_entry_type, atr_recommended_position_percent, atr_immediate_entry_allowed, entry_authority, entry_authority_max_position_percent, latest_price, stop_loss, take_profit, rsi_score, sma20_score FROM crypto_ai.trade_signal WHERE id IN (156723, 159408, 165412, 167668, 171589, 176710, 159285, 159407, 165415, 176655) ORDER BY id LIMIT 12;
SELECT p.id AS position_id, COUNT(*) AS n, MIN(s.latest_price) AS ref_low_30m, MAX(s.latest_price) AS high_30m, SUBSTRING_INDEX(GROUP_CONCAT(DATE_FORMAT(s.generated_at, '%H:%i:%s') ORDER BY s.latest_price DESC, s.generated_at DESC), ',', 1) AS high_at FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal e ON e.id = p.signal_id JOIN crypto_ai.trade_signal s ON s.symbol = e.symbol AND s.interval_code = '1m' AND s.generated_at BETWEEN e.generated_at - INTERVAL 30 MINUTE AND e.generated_at WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id ORDER BY p.id LIMIT 10;